#include "material_library_page.hpp"
#include "material_library_store.hpp"
#include <QtWidgets>
#include "page_snapshot_reader.hpp"
namespace {
class Page:public QWidget {
public:
PageSnapshotReader* snapshotReader=nullptr;bool snapshotReady=false;QJsonObject cleanState,externalState;bool hasExternalState=false;QString filePath;MaterialLibraryStore store;MaterialLibrarySources sources;SourceHandoffOpener opener;QJsonArray all,matches,baselineTags;QJsonObject current,baseline,pending,heads;QString expected,revision;int page=0;bool loading=false;QStackedWidget* stack;QLineEdit *search,*category,*tags;QPlainTextEdit *body,*notes,*preview;QListWidget* list;QComboBox* order;QMap<QString,QComboBox*> filters;QLabel* status;QPushButton *previous,*next;
Page(QString file,QWidget*p,MaterialLibrarySources s,SourceHandoffOpener o):QWidget(p),filePath(file),store(file,true),sources(s),opener(o){auto outer=new QVBoxLayout(this);stack=new QStackedWidget(this);outer->addWidget(stack,1);status=new QLabel(this);status->setWordWrap(true);status->setTextFormat(Qt::PlainText);outer->addWidget(status);auto main=new QWidget(stack);stack->addWidget(main);auto l=new QVBoxLayout(main);l->addWidget(new QLabel("资料库 · 按标题、内容与分类检索",main));search=new QLineEdit(main);search->setObjectName("materialLibrarySearch");search->setPlaceholderText("检索全部标题、完整正文、原标签与人工分类");l->addWidget(search);auto grid=new QGridLayout;l->addLayout(grid);QStringList keys{"source","topic","type","category"},labels{"来源/作者","原主题","原资料类型","人工分类"};for(int i=0;i<4;++i){auto c=new QComboBox(main);c->setObjectName("materialLibrary_"+keys[i]);filters[keys[i]]=c;grid->addWidget(new QLabel(labels[i],main),0,i);grid->addWidget(c,1,i);connect(c,qOverload<int>(&QComboBox::currentIndexChanged),this,[=](int){if(!loading){page=0;render();persist();}});}order=new QComboBox(main);order->addItem("最新在前","latest");order->addItem("最早在前","earliest");l->addWidget(order);list=new QListWidget(main);list->setObjectName("materialLibraryRows");l->addWidget(list,1);auto row=new QHBoxLayout;l->addLayout(row);auto btn=[&](QBoxLayout* target,QString text,std::function<void()> action){auto b=new QPushButton(text,this);target->addWidget(b);connect(b,&QPushButton::clicked,this,[=]{guard(action);});return b;};previous=btn(row,"上一页",[=]{if(page>0)--page;render();persist();});next=btn(row,"下一页",[=]{if((page+1)*20<matches.size())++page;render();persist();});btn(row,"完整原文/分类",[=]{if(!list->currentItem())throw std::runtime_error("先选择资料");choose(list->currentItem()->data(Qt::UserRole).toJsonObject());});btn(row,"重读全量资料",[=]{refresh();persist();});btn(row,"历史分类",[=]{preview->setPlainText(QString::fromUtf8(QJsonDocument(store.history()).toJson(QJsonDocument::Indented)));stack->setCurrentIndex(2);});
auto reader=new QWidget(stack);stack->addWidget(reader);auto r=new QVBoxLayout(reader);btn(r,"返回检索",[=]{stack->setCurrentIndex(0);persist();});body=new QPlainTextEdit(reader);body->setReadOnly(true);body->setObjectName("materialLibraryBody");r->addWidget(body,1);auto form=new QFormLayout;r->addLayout(form);category=new QLineEdit(reader);category->setObjectName("materialLibraryCategory");tags=new QLineEdit(reader);tags->setObjectName("materialLibraryTags");notes=new QPlainTextEdit(reader);notes->setObjectName("materialLibraryNotes");notes->setMaximumHeight(100);form->addRow("人工分类",category);form->addRow("人工标签（用英文分号分隔）",tags);form->addRow("人工笔记",notes);auto actions=new QHBoxLayout;r->addLayout(actions);btn(actions,"保存人工分类",[=]{if(fields()==baseline){status->setText("分类未变化；未新增记录");return;}auto ref=current.value("reference").toObject();materialLibrary::resolve(ref,sources?sources():QJsonArray{});auto record=materialLibrary::classification(ref,category->text(),tagArray(),notes->toPlainText(),expected);store.save(record,expected);expected=record.value("id").toString();baselineTags=record.value("tags").toArray();baseline=fields();heads=store.heads();refresh();body->setPlainText(materialLibrary::read(current,record));persist();status->setText("人工分类已保存；原文未修改");});btn(actions,"放弃未保存分类",[=]{loading=true;category->setText(baseline.value("category").toString());tags->setText(baseline.value("tagsText").toString());notes->setPlainText(baseline.value("notes").toString());loading=false;persist();});btn(actions,"回到准确现有来源",[=]{if(!opener)throw std::runtime_error("宿主未接来源入口");auto ref=current.value("reference").toObject();auto raw=materialLibrary::resolve(ref,sources?sources():QJsonArray{});opener(ref.value("kind").toString(),raw);});
auto io=new QWidget(stack);stack->addWidget(io);auto il=new QVBoxLayout(io);btn(il,"返回检索",[=]{stack->setCurrentIndex(0);persist();});preview=new QPlainTextEdit(io);preview->setReadOnly(true);il->addWidget(preview,1);btn(il,"确认分类导入（保留本机现有分类）",[=]{if(pending.isEmpty())throw std::runtime_error("没有已预览分类备份");store.merge(pending);pending={};heads=store.heads();refresh();persist();status->setText("已合并独立分类历史；现有分类及原文未覆盖");});btn(il,"取消预览",[=]{pending={};persist();stack->setCurrentIndex(0);});auto files=new QHBoxLayout;outer->addLayout(files);btn(files,"预览分类备份导入",[=]{auto path=QFileDialog::getOpenFileName(this,"选择分类备份",{},"JSON (*.json)");if(path.isEmpty())return;QFile f(path);business::require(f.open(QIODevice::ReadOnly)&&f.size()<=25*1024*1024,"文件不可读或过大");auto candidate=store.preview(f.readAll());pending=candidate;preview->setPlainText(QString::fromUtf8(QJsonDocument(pending).toJson(QJsonDocument::Indented)));stack->setCurrentIndex(2);persist();});btn(files,"导出全部分类历史",[=]{auto b=store.backup();auto path=QFileDialog::getSaveFileName(this,"导出分类历史","material-library.json","JSON (*.json)");if(path.isEmpty())return;QSaveFile f(path);business::require(f.open(QIODevice::WriteOnly)&&f.write(b)==b.size()&&f.commit(),"导出失败");status->setText("已完整导出分类历史，未导出草稿");});connect(search,&QLineEdit::textChanged,this,[=]{if(!loading){page=0;render();persist();}});connect(order,qOverload<int>(&QComboBox::currentIndexChanged),this,[=](int){if(!loading){page=0;render();persist();}});for(auto edit:{category,tags})connect(edit,&QLineEdit::textChanged,this,[=]{if(!loading)persist();});connect(notes,&QPlainTextEdit::textChanged,this,[=]{if(!loading)persist();});loading=true;auto retry=new QPushButton("重读资料快照",this);retry->setObjectName("materialLibraryRetry");outer->addWidget(retry);snapshotReader=new PageSnapshotReader(this,snapshotRead(),[this](QJsonObject data,QString error){if(!error.isEmpty()){setEnabled(true);status->setText("资料读取暂未完成："+error+"；已有草稿与结果保留，可重读。");return;}bool first=!snapshotReady;if(!first&&data.value("requestedQuery").toObject()!=query()){refresh();return;}auto candidate=data.value("materials").toArray();auto saved=data.value("state").toObject();applyMaterials(candidate,data.value("heads").toObject(),data.value("options").toObject());matches=data.value("matches").toArray();snapshotReady=true;setProperty("materialSnapshotReady",true);if(first){revision=saved.value("revision").toString();restore(hasExternalState?externalState:saved,true);cleanState=save();hasExternalState=false;}else renderRows();loading=false;setEnabled(true);});connect(retry,&QPushButton::clicked,this,[this]{refresh();});status->setText("正在后台读取材料与分类草稿；可离开页面。");setEnabled(false);loading=false;snapshotReader->request();}
void guard(std::function<void()> fn){try{fn();}catch(const std::exception&e){status->setText(QString::fromUtf8(e.what()));}}
QJsonArray tagArray()const{if(tags->text()==baseline.value("tagsText").toString())return baselineTags;QJsonArray result;if(tags->text().isEmpty())return result;for(auto t:tags->text().split(";",Qt::KeepEmptyParts))result.append(t);return result;}
QJsonObject fields()const{return {{"category",category->text()},{"tagsText",tags->text()},{"notes",notes->toPlainText()}};}
QJsonObject query()const{QJsonObject q{{"search",search->text()},{"order",order->currentData().toString()}};for(auto i=filters.begin();i!=filters.end();++i)q[i.key()]=i.value()->currentData().toString();return q;}
std::function<QJsonObject()> snapshotRead()const{auto selected=hasExternalState?externalState.value("query").toObject():query();bool useSaved=!snapshotReady&&!hasExternalState;return [file=filePath,readSources=sources,selected,useSaved]{business::require(bool(readSources),"宿主未提供后台安全的本机来源");auto candidate=materialLibrary::materials(readSources());auto data=MaterialLibraryStore::readOnlySnapshot(file);auto heads=data.value("heads").toObject();QMap<QString,QSet<QString>> sets;for(auto v:candidate){auto m=v.toObject();for(auto k:{"source","topic","type"})sets[k].insert(m.value(k).toString());auto category=heads.value(materialLibrary::key(m.value("reference").toObject())).toObject().value("category").toString();sets["category"].insert(category.isEmpty()?QString("未分类"):category);}QJsonObject options;auto q=useSaved?data.value("state").toObject().value("query").toObject():selected;for(auto i=sets.begin();i!=sets.end();++i){auto values=i.value().values();values.sort();QJsonArray array;for(auto value:values)array.append(value);options[i.key()]=array;if(!i.value().contains(q.value(i.key()).toString()))q[i.key()]="";}data["requestedQuery"]=selected;data["materials"]=candidate;data["options"]=options;data["matches"]=materialLibrary::filter(candidate,q,heads);return data;};}
void refresh(){status->setText("正在后台读取材料；已有筛选、原文和人工稿保留。");if(snapshotReader)snapshotReader->request(snapshotRead());}
void applyMaterials(QJsonArray candidate,QJsonObject snapshotHeads,QJsonObject options){auto old=query();all=candidate;heads=snapshotHeads;bool was=loading;loading=true;for(auto i=filters.begin();i!=filters.end();++i){auto c=i.value();c->clear();c->addItem("全部","");for(auto value:options.value(i.key()).toArray()){auto text=value.toString();c->addItem(text,text);}int index=c->findData(old.value(i.key()).toString());c->setCurrentIndex(index<0?0:index);}loading=was;}
void render(){matches=materialLibrary::filter(all,query(),heads);renderRows();}
void renderRows(){page=qBound(0,page,qMax(0,(matches.size()-1)/20));list->clear();for(int i=page*20;i<qMin(matches.size(),(page+1)*20);++i){auto m=matches[i].toObject();auto item=new QListWidgetItem(m.value("title").toString()+" / "+m.value("source").toString()+" / "+m.value("type").toString(),list);item->setData(Qt::UserRole,m);}previous->setEnabled(page>0);next->setEnabled((page+1)*20<matches.size());status->setText(QString("全量 %1 · 匹配 %2 · 第%3/%4页 · 人工标签不是事实").arg(all.size()).arg(matches.size()).arg(page+1).arg(qMax(1,(matches.size()+19)/20)));}
void choose(const QJsonObject& m){if(!current.isEmpty()&&fields()!=baseline)throw std::runtime_error("分类有未保存修改；先保存或明确放弃");current=m;auto c=heads.value(materialLibrary::key(m.value("reference").toObject())).toObject();expected=c.value("id").toString();loading=true;category->setText(c.value("category").toString());QStringList ts;for(auto t:c.value("tags").toArray())ts<<t.toString();tags->setText(ts.join(";"));notes->setPlainText(c.value("notes").toString());baselineTags=c.value("tags").toArray();baseline=fields();loading=false;body->setPlainText(materialLibrary::read(m,c));stack->setCurrentIndex(1);persist();}
QJsonObject save()const{return {{"query",query()},{"page",page},{"current",current},{"baseline",baseline},{"baselineTags",baselineTags},{"expectedHead",expected},{"fields",fields()},{"pending",pending},{"view",stack->currentIndex()}};}
void persist(){if(loading||!snapshotReady)return;auto state=save();if(state==cleanState)return;guard([=]{revision=store.saveState(state,revision);cleanState=state;});}
void restore(const QJsonObject& s,bool prepared=false){if(!snapshotReady){externalState=s;hasExternalState=true;refresh();return;}bool was=loading;loading=true;auto q=s.value("query").toObject();search->setText(q.value("search").toString());for(auto i=filters.begin();i!=filters.end();++i){int index=i.value()->findData(q.value(i.key()).toString());i.value()->setCurrentIndex(index<0?0:index);}order->setCurrentIndex(q.value("order")=="earliest"?1:0);page=qMax(0,s.value("page").toInt());current=s.value("current").toObject();baseline=s.value("baseline").toObject();baselineTags=s.value("baselineTags").toArray();expected=s.value("expectedHead").toString();auto f=s.value("fields").toObject();category->setText(f.value("category").toString());tags->setText(f.value("tagsText").toString());notes->setPlainText(f.value("notes").toString());pending=s.value("pending").toObject();body->setPlainText(materialLibrary::read(current,heads.value(materialLibrary::key(current.value("reference").toObject())).toObject()));preview->setPlainText(QString::fromUtf8(QJsonDocument(pending).toJson(QJsonDocument::Indented)));stack->setCurrentIndex(qBound(0,s.value("view").toInt(),2));loading=was;if(prepared)renderRows();else render();}
};
}
QWidget* materialLibraryPage(const QString& f,QWidget*p,MaterialLibrarySources s,SourceHandoffOpener o){return new Page(f,p,s,o);}
bool materialLibraryBack(QWidget*w){auto p=dynamic_cast<Page*>(w);if(!p||p->stack->currentIndex()==0)return false;p->stack->setCurrentIndex(0);p->persist();return true;}
QJsonObject materialLibrarySaveState(QWidget*w){auto p=dynamic_cast<Page*>(w);return p?p->save():QJsonObject{};}
void materialLibraryRestoreState(QWidget*w,const QJsonObject&s){if(auto p=dynamic_cast<Page*>(w))p->restore(s);}



